<h1 id="d-vs-silq-types">D vs Silq types</h1>
<table>
 <thead>
 <tr>
 <th>Construct</th>
 <th style="text-align: center">D</th>
 <th style="text-align: center">Silq</th>
 </tr>
 </thead>
 <tbody>
 <tr>
 <td>Boolean</td>
 <td style="text-align: center"><code class="code-inline language-d"><span style="color:#8be9fd">bool</span></code></td>
 <td style="text-align: center"><code class="language-silq">!B</code>
 / <code class="language-silq">!𝔹</code>
</td>
 </tr>
 <tr>
 <td>8-bit unsigned integer</td>
 <td style="text-align: center"><code class="code-inline language-d"><span style="color:#8be9fd">ubyte</span></code></td>
 <td style="text-align: center"><code class="language-silq">!uint[8]</code>
</td>
 </tr>
 <tr>
 <td>32-bit signed integer</td>
 <td style="text-align: center"><code class="code-inline language-d"><span style="color:#8be9fd">int</span></code></td>
 <td style="text-align: center"><code class="language-silq">!int[32]</code>
</td>
 </tr>
 <tr>
 <td>Tuple type</td>
 <td style="text-align: center"><code class="code-inline language-d">Tuple<span style="color:#ff79c6">!(</span>S<span style="color:#ff79c6">,</span>T<span style="color:#ff79c6">,</span>U<span style="color:#ff79c6">)</span></code></td>
 <td style="text-align: center"><code class="language-silq">S x T x U</code>
 / <code class="language-silq">S × T × U</code>
</td>
 </tr>
 <tr>
 <td>Fixed-length array</td>
 <td style="text-align: center"><code class="code-inline language-d">T<span style="color:#ff79c6">[</span>n<span style="color:#ff79c6">]</span></code></td>
 <td style="text-align: center"><code class="language-silq">T^n</code>
 = <code class="language-silq">T × T × ⋯ × T</code>
</td>
 </tr>
 <tr>
 <td>Dependent-length array</td>
 <td style="text-align: center">No</td>
 <td style="text-align: center"><code class="language-silq">T^n</code>
 (<code>n</code> a runtime expression)</td>
 </tr>
 <tr>
 <td>Dynamic-length array</td>
 <td style="text-align: center"><code class="code-inline language-d">T<span style="color:#ff79c6">[]</span></code> (slice)</td>
 <td style="text-align: center"><code class="language-silq">T[]</code>
 (value type)</td>
 </tr>
 <tr>
 <td>Effects</td>
 <td style="text-align: center">e.g. <code class="code-inline language-d"><span style="color:#8be9fd;font-style:italic">pure</span></code></td>
 <td style="text-align: center"><code class="language-silq">qfree</code>
 / <code class="language-silq">mfree</code>
 / <code class="language-silq">wild</code>
</td>
 </tr>
 <tr>
 <td>Closures</td>
 <td style="text-align: center"><code class="code-inline language-d">B <span style="color:#50fa7b">delegate</span><span style="color:#ff79c6">(</span>A<span style="color:#ff79c6">)</span></code></td>
 <td style="text-align: center"><code class="language-silq">a -&gt; b</code>
 / <code class="language-silq">a → b</code>
</td>
 </tr>
 <tr>
 <td>Closures with effects</td>
 <td style="text-align: center"><code class="code-inline language-d">B <span style="color:#50fa7b">delegate</span><span style="color:#ff79c6">(</span>A<span style="color:#ff79c6">)</span><span style="color:#8be9fd;font-style:italic">pure</span></code></td>
 <td style="text-align: center"><code class="language-silq">A -&gt;qfree B</code>
 / <code class="language-silq">A →qfree B</code>
</td>
 </tr>
 </tbody>
</table>
