<h1 id="nb-initialization">NB: Initialization</h1>
<div class="twocolumn" style="--twocolumn-left:1fr;--twocolumn-right:1fr;--twocolumn-gap:1.5rem;--twocolumn-width:100%;--twocolumn-align:start"><div class="twocolumn-column"><div class="highlight"><pre tabindex="0" class="chroma"><code class="language-d" data-lang="d"><span class="line"><span class="cl"><span class="kt">float</span> <span class="n">f</span><span class="o">;</span> <span class="c1">// initialize?
</span></span></span><span class="line"><span class="cl"><span class="c1"></span><span class="k">if</span><span class="o">(</span><span class="n">x</span><span class="o">){</span>
</span></span><span class="line"><span class="cl">	<span class="n">f</span> <span class="o">=</span> <span class="mf">2.5f</span><span class="o">;</span>
</span></span><span class="line"><span class="cl"><span class="o">}</span><span class="k">else</span><span class="o">{</span>
</span></span><span class="line"><span class="cl">	<span class="n">f</span> <span class="o">=</span> <span class="mf">3.1f</span><span class="o">;</span>
</span></span><span class="line"><span class="cl"><span class="o">}</span>
</span></span><span class="line"><span class="cl"><span class="k">return</span> <span class="n">f</span><span class="o">;</span></span></span></code></pre></div></div>

<div class="twocolumn-column"><pre class="silq-code-window"><code class="language-silq">// no initializer needed
if x {
	f := 2.5;
}else{
	f := 3.1;
}
return f;</code></pre></div></div>

